pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract ProofFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        set(v);
    }

    function set(uint256 v) public {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract ProofMirror is ISwarmFeed {
    ISwarmFeed private immutable p;

    constructor(ISwarmFeed p_) {
        p = p_;
    }

    function latestValue() external view returns (uint256, uint64) {
        return p.latestValue();
    }

    function isStale() external view returns (bool) {
        return p.isStale();
    }

    function maxAge() external view returns (uint256) {
        return p.maxAge();
    }
}

/// @dev ETH/USD = $2000, always fresh.
contract ProofAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @dev A borrower that is a contract, so a wipe, a redemption and a redraw can share one transaction.
contract Borrower {
    ParameterizedVault private immutable vault;

    constructor(ParameterizedVault vault_, MockIMD imd) {
        vault = vault_;
        imd.approve(address(vault_), type(uint256).max);
    }

    function lock(uint256 amount) external {
        vault.lock(amount);
    }

    function draw(uint256 amount) external {
        vault.draw(amount);
    }

    function cash(uint256 amount, address candidate) external returns (uint256) {
        return vault.cash(amount, 0, candidate);
    }

    /// Repay for the length of the call, redeem against the shrunken supply, borrow it back.
    function wipeCashRedraw(uint256 repaid, uint256 burned, address candidate) external returns (uint256) {
        vault.wipe(repaid);
        uint256 out = vault.cash(burned, 0, candidate);
        vault.draw(repaid);
        return out;
    }
}

/// @notice A repayment that exists only for the length of the call inflates the backing a redemption
/// in the same call is paid against. CDPVault nets out same-transaction DEPOSITS and MINTS
/// (SECURED_THIS_TX_SLOT, MINTED_THIS_TX_SLOT) and, since 8756817, leaves the lag where it was when
/// debt leaves and returns inside one transaction (_clampLag); but imdUSD BURNED in the transaction
/// still leaves `stablecoin.totalSupply()`, the denominator of _backingPerUnit. A borrower in the
/// 170-200% band repays up to (debt - collateral*price/2) without moving its secured term, so the
/// numerator holds while the denominator falls, and the redemption it then takes is paid above the
/// honest pro-rata figure. The redraw restores debt and supply, and the lag netting means it costs
/// nothing afterwards either. Fails on the committed code; passes once same-transaction repayment is
/// added back to the supply (and prior debt) the backing is measured against.
contract Proof_SameTxWipeInflatesRedemption is Test {
    address private constant OTHER = address(0xB1);
    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    ProofFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ProofAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new ProofFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        ProofFeed health = new ProofFeed(0.85 ether); // mat 170, gap 50: candidates below 220%
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new ProofMirror(primary))
        );
        stable = vault.stablecoin();
        vm.prank(APPROVED_OPERATOR);
        imd.mint(OTHER, 10_000 ether);
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);
    }

    function _priceUsd(uint256 usd) private {
        primary.set(usd * 1e18 / 2000 ether);
    }

    function test_aSameTransactionRepaymentMustNotInflateTheRedemptionPayout() public {
        Borrower borrower = new Borrower(vault, imd);
        vm.prank(APPROVED_OPERATOR);
        imd.mint(address(borrower), 10_000 ether);
        // The borrower at 578%, another position at 170%; the other hands the borrower its imdUSD.
        borrower.lock(5_780 ether);
        borrower.draw(1_000 ether);
        vm.startPrank(OTHER);
        vault.lock(5_100 ether);
        vault.draw(3_000 ether);
        stable.transfer(address(borrower), 3_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        // A crash to $0.294: the borrower sits at 170% (redeemable, healthy), the other at 50%.
        _priceUsd(0.294 ether);
        borrower.lock(1);
        vm.prank(OTHER);
        vault.lock(1);
        vm.warp(block.timestamp + 3 days); // everything warm
        borrower.lock(1);
        uint256 backing = vault.backingPerUnit();
        assertLt(backing, 1e18, "the regime: backing below par");

        uint256 snapshot = vm.snapshotState();
        uint256 honest = borrower.cash(500 ether, address(borrower));
        vm.revertToState(snapshot);

        // Same end state for debt and supply, but the redemption inside the call is paid against a
        // supply shrunk by the 150 imdUSD repaid for the length of the call.
        uint256 boosted = borrower.wipeCashRedraw(150 ether, 500 ether, address(borrower));
        emit log_named_uint("honest payout (IMD)", honest);
        emit log_named_uint("payout with a same-call wipe and redraw (IMD)", boosted);
        assertLe(boosted, honest, "a repayment that lasts only for the call must not inflate the payout");
    }
}

