import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract FeeFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;
    uint64 private updatedAt;

    constructor(uint256 v) {
        value = v;
        updatedAt = uint64(block.timestamp);
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, updatedAt);
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract FeeMirror is ISwarmFeed {
    ISwarmFeed private immutable primary;

    constructor(ISwarmFeed p) {
        primary = p;
    }

    function latestValue() external view returns (uint256, uint64) {
        return primary.latestValue();
    }

    function isStale() external view returns (bool) {
        return primary.isStale();
    }

    function maxAge() external view returns (uint256) {
        return primary.maxAge();
    }
}

contract FeeAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @dev A dominant borrower that burns its own principal, redeems against the shrunken supply and
/// draws the principal back, in one transaction.
contract Pumper {
    ParameterizedVault private immutable vault;

    constructor(ParameterizedVault vault_, MockIMD imd) {
        vault = vault_;
        imd.approve(address(vault_), type(uint256).max);
    }

    function open(uint256 collateral, uint256 debt) external {
        vault.lock(collateral);
        vault.draw(debt);
    }

    function pump(uint256 principal, uint256 redeemed) external {
        vault.wipe(principal);
        vault.cash(redeemed, 0, address(0));
        vault.draw(principal);
    }
}

/// @notice Q6: `_redemptionRate` nets supply MINTED this transaction out of the fee base (finding
/// fcd5b261) but not supply BURNED this transaction. A borrower holding most of the supply as debt
/// wipes it, redeems a small amount against the shrunken supply, and draws the debt back: the base
/// rate everyone pays afterwards is pinned at the cap for a tenth of the honest cost.
contract RedemptionFeeBaseBurnTest is Test {
    address private constant OTHER = address(0x07);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    Pumper private pumper;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new FeeAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        FeeFeed primary = new FeeFeed(uint256(1 ether) * 1e18 / 2000 ether);
        FeeFeed health = new FeeFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new FeeMirror(primary))
        );
        stable = vault.stablecoin();
        pumper = new Pumper(vault, imd);
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(address(pumper), 2_000 ether);
        imd.mint(OTHER, 200 ether);
        imd.mint(address(vault.treasury()), 100 ether); // a reserve, so the redemption is reserve-funded
        vm.stopPrank();
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);
    }

    function test_burningSupplyInTheSameTransactionShrinksTheFeeBase() public {
        pumper.open(2_000 ether, 900 ether);
        vm.startPrank(OTHER);
        vault.lock(200 ether);
        vault.draw(100 ether);
        stable.transfer(address(pumper), 9 ether);
        vm.stopPrank();
        assertEq(stable.totalSupply(), 1_000 ether);
        assertEq(vault.redemptionBaseRate(), 0);

        // The honest increase for burning 9 imdUSD of a 1,000 supply at divisor 2: 9 / 1000 / 2 = 0.45%.
        uint256 honest = vault.redemptionFeeBps(9 ether);
        assertEq(honest, 50 + 45, "quoted: floor 50 bps plus 45");

        // Wipe 900, cash 9 against the 100 that remain, draw 900 back. The 9 is charged
        // 9 / 100 / 2 = 4.5%: the cap, for everyone, until it decays (half-life twelve hours).
        pumper.pump(900 ether, 9 ether);
        (, uint256 debt) = vault.positions(address(pumper));
        assertEq(debt, 900 ether, "the pumper's position is unchanged");
        assertEq(stable.totalSupply(), 991 ether);

        // Expected (NatSpec of _redemptionRate: "the burned fraction of the supply that existed before
        // this transaction"): 0.45% -> base rate 0.0045e18. Actual: 0.045e18, the cap.
        assertLe(vault.redemptionBaseRate(), 0.0045e18 + 1, "the base rate must be measured against the pre-transaction supply");
        // Cost comparison on the committed code: without the trick, reaching the cap takes a burn of 9% of
        // supply (90 imdUSD at the 5% fee: 4.5 imdUSD lost); with it, 9 imdUSD at the same fee: 0.45.
        // Afterwards redemptionFeeBps(0) reads 500 for every later redeemer until the base decays.
    }
}

