// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {CDPVault} from "src/CDPVault.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {MockWorkOracle} from "src/MockWorkOracle.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {Parameters} from "src/Parameters.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract LegFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 private value;

    constructor(uint256 v) {
        value = v;
    }

    function set(uint256 v) external {
        value = v;
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, uint64(block.timestamp));
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract LegMirror is ISwarmFeed {
    ISwarmFeed private immutable primary;

    constructor(ISwarmFeed p) {
        primary = p;
    }

    function latestValue() external view returns (uint256, uint64) {
        return primary.latestValue();
    }

    function isStale() external view returns (bool) {
        return primary.isStale();
    }

    function maxAge() external view returns (uint256) {
        return primary.maxAge();
    }
}

contract LegAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @notice FINDING (CDPVault._resecure, the 8756817 "term kept" branch): while the ETH/USD leg cannot be
/// read, a repayment through the ungated `wipe` leaves the position's secured term at its old level
/// (min(before, collateral)) although the term is bounded by 2 x principal / price and the principal just
/// fell. The overstatement survives the leg's recovery until THAT position is touched again, which its
/// owner need never do, and `cash` (gated: it runs only after the leg is back) pays every redeemer against
/// the overstated backing. Below: the honest post-wipe backing is 0.68; the vault reads par.
contract DeadLegKeepsSecuredTermTest is Test {
    address private constant WIPER = address(0xCA);
    address private constant OTHER = address(0x0B);
    address private constant REDEEMER = address(0x4ED);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;
    LegFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new LegAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new LegFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        LegFeed health = new LegFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new LegMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        vm.startPrank(APPROVED_OPERATOR);
        oracle.grantRights(WIPER, 1_000 ether);
        imd.mint(WIPER, 2_001 ether);
        imd.mint(OTHER, 1_700 ether);
        vm.stopPrank();
        vm.prank(WIPER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(OTHER);
        imd.approve(address(vault), type(uint256).max);
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    function test_aWipeDuringAnOutageOverstatesSecuredCollateralAfterRecovery() public {
        vm.startPrank(WIPER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether); // 200%: term 2,000
        vm.stopPrank();
        vm.startPrank(OTHER);
        vault.lock(1_700 ether);
        vault.draw(1_000 ether); // 170%: term 1,700
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        vm.prank(WIPER);
        vault.earn(500 ether); // the warmed ceiling: 25% of 2,000
        vm.warp(block.timestamp + 3 days);
        // IMD falls to $0.60: both positions underwater, nobody has liquidated yet; backing below par.
        primary.set(uint256(0.6 ether) * 1e18 / 2000 ether);
        uint256 beforeOutage = vault.backingPerUnit();
        assertLt(beforeOutage, 0.9e18, "below par after the fall");

        // The ETH/USD leg dies: every priced action halts, `wipe` does not.
        vm.mockCallRevert(CHAINLINK_ETH_USD, abi.encodeWithSignature("latestRoundData()"), "dead");
        vm.prank(WIPER);
        vm.expectRevert(CDPVault.StaleFeed.selector);
        vault.cash(1 ether, 0, OTHER);
        vm.prank(WIPER);
        vault.wipe(999 ether); // principal 1,000 -> about 1.4, term should fall to 2 x 1.4 / 0.6
        vm.clearMockedCalls();

        uint256 readAfterRecovery = vault.backingPerUnit();
        uint256 securedRead = vault.securedCollateral();
        // Touch the wiper's position at a live price: this is the figure the term should have had.
        vm.prank(WIPER);
        vault.lock(1);
        uint256 honest = vault.backingPerUnit();
        uint256 securedHonest = vault.securedCollateral();
        emit log_named_decimal_uint("securedCollateral read after the leg recovered", securedRead, 18);
        emit log_named_decimal_uint("securedCollateral once the position is re-priced", securedHonest, 18);
        emit log_named_decimal_uint("backingPerUnit read after the leg recovered", readAfterRecovery, 18);
        emit log_named_decimal_uint("backingPerUnit once the position is re-priced", honest, 18);
        assertLe(securedRead, securedHonest, "a dead leg must not leave more secured collateral than a live price would");
        assertLe(readAfterRecovery, honest, "redeemers must not be paid against backing a live price would not show");
    }

    /// @dev The same state, read through the payout: a 100 imdUSD burn against OTHER takes 165.8 IMD
    /// where the live-priced backing pays 112.9.
    function test_aRedeemerIsOverpaidFromTheCandidateBeforeThePositionIsTouched() public {
        vm.startPrank(WIPER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(OTHER);
        vault.lock(1_700 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        vm.prank(WIPER);
        vault.earn(500 ether);
