/// @notice `cover`'s bad-debt sweep (CDPVault.cover, the `recorded != 0 && value < recorded` branch) takes
/// a re-collateralised borrower's WHOLE collateral for whatever `amount` the caller names, as little as
/// one wei of debt, skipping the mark, the grace and the 120% seizure formula every other underwater
/// position gets.
contract CoverSweepStripsTest is Test {
    address private constant BORROWER = address(0xB0);
    address private constant KEEPER = address(0xCA);
    address private constant STRANGER = address(0x57);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    SweepFeed private primary;

    /// 1 IMD = 1/2000 ETH and 1 ETH = $2000: the vault prices IMD at exactly $1 per 1e18 raw units.
    uint256 private constant ONE_DOLLAR = uint256(1 ether) * 1e18 / 2000 ether;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new SweepAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new SweepFeed(ONE_DOLLAR);
        SweepFeed health = new SweepFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new SweepMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 10_000 ether);
        imd.mint(KEEPER, 100_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(KEEPER);
        imd.approve(address(vault), type(uint256).max);
    }

    function _setDollars(uint256 usdPerImd) private {
        primary.set(ONE_DOLLAR * usdPerImd / 1 ether);
    }

    /// @dev BORROWER at exactly mat (1700 / 1000) is crashed to $0.50, marked, and bitten for everything its
    /// collateral covers; the rest of its debt is realized bad debt.
    function _drain() private returns (uint256 bad) {
        vm.startPrank(BORROWER);
        vault.lock(1_700 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(KEEPER);
        vault.lock(20_000 ether);
        vault.draw(5_000 ether);
        vm.stopPrank();
        _setDollars(0.5 ether);
        vault.bark(BORROWER);
        vm.warp(block.timestamp + 6 hours);
        _setDollars(0.5 ether);
        uint256 repayable = uint256(1_700 ether) * 0.5 ether / 1.2e18;
        vm.prank(KEEPER);
        vault.bite(BORROWER, repayable);
        (uint256 held,) = vault.positions(BORROWER);
        assertEq(held, 0, "drained");
        bad = vault.totalBadDebt();
        assertGt(bad, 0, "realized");
        _setDollars(1 ether);
    }

    function test_coverSweepStripsAReCollateralisedBorrowerForOneWei() public {
        uint256 bad = _drain();
        // The Treasury holds imdUSD (the fees the bite reminted to it, topped up by the keeper).
        address treasury = address(vault.treasury());
        vm.prank(KEEPER);
        stable.transfer(treasury, 10 ether);

        // The borrower re-collateralises to a healthy 200%+ loan, as the totalBadDebt NatSpec says it may.
        uint256 relock = bad * 2;
        vm.prank(BORROWER);
        vault.lock(relock);
        assertGe(vault.collateralRatio(BORROWER), 170, "healthy again");
        vm.expectRevert(CDPVault.NoRealizedBadDebt.selector);
        vault.cover(BORROWER, 1);

        // The market falls 55%: collateral worth 0.9 x the recorded bad debt. Any other underwater position
        // would now need a mark, up to six hours of grace, and a bite that seizes 1.2 x the debt it repays.
        _setDollars(0.45 ether);
        uint256 debtBefore = vault.debtOf(BORROWER);
        uint256 valueBefore = relock * 0.45 ether / 1e18;
        assertLt(valueBefore, bad, "worth less than the recorded bad debt");

        vm.prank(STRANGER);
        (bool ok,) = address(vault).call(abi.encodeCall(CDPVault.cover, (BORROWER, 1)));
        if (!ok) return; // a cover that refuses leaves the borrower on the liquidation path: fine

        (uint256 heldAfter,) = vault.positions(BORROWER);
        uint256 debtAfter = vault.debtOf(BORROWER);
        uint256 cancelled = debtBefore - debtAfter;
        uint256 taken = relock - heldAfter;
        // EXPECTED: collateral leaves the borrower only against debt it retires, at no worse than the bite
        // formula (1.2 x the debt repaid, at the same price). ACTUAL: all 583 IMD (worth 262 imdUSD) go to
        // the Treasury and the borrower's debt falls by one wei.
        assertLe(
            taken * 0.45 ether / 1e18,
            cancelled * 12 / 10 + 1,
            "collateral swept by cover must be credited against the debt it stood behind"
        );
    }
}

