/// @notice `_resecure` keeps a position's secured term when the price reads zero. A wipe made while the
/// ETH/USD leg is down then leaves the term at its pre-wipe size (bounded by 2 x the OLD principal), so once
/// the leg is back `securedCollateral` overstates what the position secures until that borrower is touched
/// again, and `backingPerUnit` reads par where the honest figure is far below it.
contract DeadLegOverstatesTest is Test {
    address private constant A = address(0xA1);
    address private constant B = address(0xB1);
    address private constant HOLDER = address(0x401D);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    LegFeed private primary;

    uint256 private constant ONE_DOLLAR = uint256(1 ether) * 1e18 / 2000 ether;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new LegAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new LegFeed(ONE_DOLLAR);
        LegFeed health = new LegFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new LegMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(A, 10_000 ether);
        imd.mint(B, 10_000 ether);
        vm.stopPrank();
        vm.prank(A);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(B);
        imd.approve(address(vault), type(uint256).max);
    }

    function _setDollars(uint256 usdPerImd) private {
        primary.set(ONE_DOLLAR * usdPerImd / 1 ether);
    }

    function test_deadLegWipeLeavesAnOverstatedSecuredTerm() public {
        // A: 2,000 IMD against 1,000 debt (200%). B: 2,000 IMD against 1,000 debt, then the market falls to
        // $0.40 so B is deeply underwater (80%) and the collateral side of the backing cap binds.
        vm.startPrank(A);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(B);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        stable.transfer(HOLDER, 500 ether);
        vm.stopPrank();
        _setDollars(0.4 ether);
        // Both positions re-priced at $0.40 and the lag fully warmed.
        vm.prank(B);
        vault.wipe(1);
        vm.warp(block.timestamp + 2 days);
        vm.prank(B);
        vault.wipe(1);
        vm.warp(block.timestamp + 2 days);
        // secured: A min(2000, 2 x 1000 / 0.4 = 5000) = 2000 IMD; B 2000 IMD. value = 4000 x 0.4 = 1600 < 1.7 x 2000.
        // supply 2000 -> backing 0.80.
        uint256 honestBefore = vault.backingPerUnit();
        assertApproxEqAbs(honestBefore, 0.8e18, 1e15, "collateral-bound backing before the outage");

        // The ETH/USD leg dies. Priced actions halt; `wipe` does not. A repays 999 of its 1,000.
        vm.mockCallRevert(CHAINLINK_ETH_USD, abi.encodeWithSignature("latestRoundData()"), "dead");
        vm.prank(A);
        vault.wipe(999 ether);
        vm.clearMockedCalls();

        // Honest: A secures min(2000, 2 x 1 / 0.4 = 5) = 5 IMD, B 2000 IMD -> value 802 against supply 1001:
        // backing 0.80. Actual: A's term is still 2,000 IMD, so value = min(4000 x 0.4, 1.7 x 1001) = 1601.6
        // and backing reads par.
        uint256 reported = vault.backingPerUnit();
        // Fees were paid first, so A's remaining debt is all principal: its honest term is 2 x that / $0.40.
        uint256 honestTermA = vault.debtOf(A) * 2e18 / (0.4 ether);
        uint256 honest = ((honestTermA + 2_000 ether) * 0.4 ether / 1e18) * 1e18 / stable.totalSupply();
        emit log_named_uint("reported backingPerUnit", reported);
        emit log_named_uint("honest   backingPerUnit", honest);
        emit log_named_uint("securedCollateral", vault.securedCollateral());
        assertLe(reported, honest + 0.01e18, "a dead-leg wipe must not leave the position securing more than 2 x its principal");
    }
}

