/// @notice Q1: the per-transaction netting of `_clampLag` (commit 8756817) is bypassed by splitting the
/// wipe and the redraw across two adjacent transactions. The borrower bears no exposure (the two
/// transactions sit in one block, no debt and no imdUSD is held in between), pays only the stability fee
/// accrued since its last touch plus gas, and leaves laggedDebt and laggedSecured at zero for a day.
/// With work-minted supply outstanding, backingPerUnit reads 0 and every `cash` reverts ZeroAmount.
contract LagChurnAcrossTransactionsTest is Test {
    address private constant WORKER = address(0xCA);
    address private constant BORROWER = address(0xB0);
    address private constant REDEEMER = address(0x4ED);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ChurnAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        // 1 IMD = 1/2000 ETH and 1 ETH = $2000: the vault prices IMD at exactly $1.
        ChurnFeed primary = new ChurnFeed(uint256(1 ether) * 1e18 / 2000 ether);
        ChurnFeed health = new ChurnFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new ChurnMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        vm.startPrank(APPROVED_OPERATOR);
        oracle.grantRights(WORKER, 1_000 ether);
        imd.mint(BORROWER, 2_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        // Minting from work switched on the governed way.
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    function test_wipeThenRedrawInAdjacentTransactionsDrivesBackingToZeroForGas() public {
        // The dominant (here: only) borrower, warmed for a day; a worker mints the ceiling against it.
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);
        vm.startPrank(WORKER);
        vault.earn(250 ether);
        stable.transfer(REDEEMER, 240 ether);
        stable.transfer(BORROWER, 10 ether); // covers the borrower's accrued stability fee
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);
        uint256 before = vault.backingPerUnit();
        assertEq(before, 1e18, "everything warm, fully backed");
        (uint256 collateralBefore,) = vault.positions(BORROWER);

        // Transaction 1: wipe everything. Transaction 2 (same block): draw it back.
        uint256 owed = vault.debtOf(BORROWER);
        vm.prank(BORROWER);
        vault.wipe(owed);
        vm.prank(BORROWER);
        vault.draw(1_000 ether);

        (uint256 collateralAfter, uint256 debtAfter) = vault.positions(BORROWER);
        assertEq(collateralAfter, collateralBefore, "nothing left the vault");
        assertEq(debtAfter, 1_000 ether, "the same principal is outstanding");
        // Cost of the churn: the stability fee accrued over two days (about 0.24 imdUSD) and gas.
        assertLt(owed - 1_000 ether, 0.3 ether, "the churn cost under 0.3 imdUSD of fees");

        // Expected (NatSpec of _backingPerUnit, "honest redemptions are not underpaid"; of _clampLag,
        // "a decrease that lasted is a decrease"): a decrease that lasted zero seconds leaves backing at par.
        // Actual: laggedDebt and laggedSecured are 0, backing reads 0 and cash reverts for everyone.
        assertEq(vault.backingPerUnit(), before, "an adjacent-transaction round trip must not move backing");
    }

    function test_cashRevertsForEveryoneAfterTheChurn() public {
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);
        vm.startPrank(WORKER);
        vault.earn(250 ether);
        stable.transfer(REDEEMER, 240 ether);
        stable.transfer(BORROWER, 10 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 1 days);
        uint256 owed = vault.debtOf(BORROWER);
        vm.prank(BORROWER);
        vault.wipe(owed);
        vm.prank(BORROWER);
        vault.draw(1_000 ether);
        // On the committed code laggedDebt and laggedSecured now read 0: transaction 1 clamped them and
        // transaction 2 found 0 as its starting level. Expected: about 9.91 IMD for 10 imdUSD (par, less
        // the 90 bps fee for a 10-of-1,250 burn). Actual: ZeroAmount.
        vm.prank(REDEEMER);
        uint256 out = vault.cash(10 ether, 0, BORROWER);
        assertGt(out, 9.8 ether, "a redeemer is paid against the honest backing");
    }
}

