        imd = new MockIMD();
        FeeFeed primary = new FeeFeed(uint256(1 ether) * 1e18 / 2000 ether);
        FeeFeed health = new FeeFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new FeeMirror(primary))
        );
