/// @notice Q3: cover's new sweep (commit 8756817) of "collateral worth less than the recorded bad debt"
/// takes collateral a bite could still reach, against a burn the caller chooses: cover(owner, 1) moves
/// the borrower's whole re-lock to the Treasury and retires one wei of debt. cover's NatSpec says it
/// "reverts on a position holding collateral a bite could still reach".
contract CoverSweepsReachableCollateralTest is Test {
    address private constant BORROWER = address(0xB0);
    address private constant KEEPER = address(0x4EE);
    address private constant ANYONE = address(0xA11);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    CoverFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new CoverAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new CoverFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        CoverFeed health = new CoverFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new CoverMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(BORROWER, 2_200 ether);
        imd.mint(KEEPER, 20_000 ether);
        vm.stopPrank();
        vm.prank(BORROWER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(KEEPER);
        imd.approve(address(vault), type(uint256).max);
    }

    /// @dev Drain the borrower: a crash to $0.50, mark, grace, and the exactly sized bite that leaves a
    /// remainder below the one-wei seizure (swept by bite, so the position records its bad debt).
    function _drain() private {
        vm.startPrank(BORROWER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(KEEPER);
        vault.lock(20_000 ether);
        vault.draw(5_000 ether);
        stable.transfer(address(vault.treasury()), 500 ether); // the surplus cover spends
        vm.stopPrank();
        primary.setValue(uint256(0.5 ether) * 1e18 / 2000 ether); // $0.50
        vm.prank(KEEPER);
        vault.bark(BORROWER);
        vm.warp(block.timestamp + 6 hours);
        primary.setValue(uint256(0.5 ether) * 1e18 / 2000 ether);
        uint256 exact = 2_000 ether * uint256(0.5e18) / 1.2e18; // the largest coverable debt
        vm.prank(KEEPER);
        vault.bite(BORROWER, exact);
        (uint256 collateral,) = vault.positions(BORROWER);
        assertEq(collateral, 0, "drained");
        assertGt(vault.totalBadDebt(), 160 ether, "about 166.7 imdUSD of realized bad debt");
    }

    function test_coverWithOneWeiTakesAWholeReLockThatABiteCouldReach() public {
        _drain();
        primary.setValue(uint256(1 ether) * 1e18 / 2000 ether); // the market recovers to $1
        uint256 record = vault.totalBadDebt();
        // The borrower starts rebuilding: lock first, repay in the next transaction.
        vm.prank(BORROWER);
        vault.lock(160 ether); // $160 against a record of about $166.7: below the record, far above dust
        (, uint256 debtBefore) = vault.positions(BORROWER);
        assertLt(160 ether, record);
        // A bite of 133 imdUSD would seize exactly 159.6 IMD of this: the collateral is reachable.
        uint256 treasuryBefore = imd.balanceOf(address(vault.treasury()));

        // Anyone retires one wei of the record. Expected per the NatSpec: revert NoRealizedBadDebt (a bite
        // can reach this collateral); or, if the sweep is intended, a burn of at least the swept value.
        // Actual: the whole 160 IMD goes to the Treasury and the borrower's debt falls by one wei.
        vm.prank(ANYONE);
        (bool ok,) = address(vault).call(abi.encodeCall(CDPVault.cover, (BORROWER, 1)));
        if (ok) {
            (uint256 collateralAfter, uint256 debtAfter) = vault.positions(BORROWER);
            uint256 swept = imd.balanceOf(address(vault.treasury())) - treasuryBefore;
            assertEq(collateralAfter, 0);
            assertEq(swept, 160 ether, "the whole re-lock was swept");
            assertGe(debtBefore - debtAfter, 160 ether, "a sweep of $160 must retire at least $160 of debt");
        }
    }
}

