/// @notice Q4: `_resecure` with an unreadable price keeps the position's previous term whole
/// (commit 8756817). An ungated `wipe` during the outage lowers the principal but not the term, so
/// `securedCollateral` carries a term no longer bounded by 2 x principal / price. After the leg returns
/// and a price fall puts honest backing below par, `cash` is paid at par from the reserve until the
/// position is touched again.
contract DeadLegWipeOverstatesSecuredTest is Test {
    address private constant A = address(0xA);
    address private constant B = address(0xB);
    address private constant REDEEMER = address(0x4ED);

    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    LegFeed private primary;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new LegAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        primary = new LegFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        LegFeed health = new LegFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new LegMirror(primary))
        );
        stable = vault.stablecoin();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(A, 1_001 ether);
        imd.mint(B, 1_000 ether);
        imd.mint(address(vault.treasury()), 100 ether); // the reserve a redemption spends first
        vm.stopPrank();
        vm.prank(A);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(B);
        imd.approve(address(vault), type(uint256).max);
    }

    function test_anUnpricedWipeLeavesATermTheNextPricedCheckpointHalves() public {
        vm.startPrank(A);
        vault.lock(1_000 ether);
        vault.draw(500 ether);
        stable.transfer(REDEEMER, 1 ether);
        vm.stopPrank();
        vm.startPrank(B);
        vault.lock(1_000 ether);
        vault.draw(500 ether);
        stable.transfer(REDEEMER, 40 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days); // everything warm
        assertEq(vault.securedCollateral(), 2_000 ether, "each term is min(1000, 2 x 500 / 1) = 1000");

        // The ETH/USD leg reverts; the collateral price reads zero. A repays all but one imdUSD.
        vm.mockCallRevert(CHAINLINK_ETH_USD, abi.encodeWithSignature("latestRoundData()"), "dead");
        vm.prank(A);
        vault.wipe(499 ether);
        vm.clearMockedCalls();
        (, uint256 debtA) = vault.positions(A);
        assertLt(debtA, 1.5 ether, "A owes about one imdUSD (plus fees)");

        // The leg is back and the market has fallen 60%: honest backing is below par.
        primary.setValue(uint256(0.4 ether) * 1e18 / 2000 ether);
        uint256 unpriced = vault.backingPerUnit();
        // Touch A at the live price: its term becomes min(1001, 2 x 1.2 / 0.4) = about 6 IMD.
        vm.prank(A);
        vault.lock(1 ether);
        uint256 priced = vault.backingPerUnit();

        // Expected: an unpriced checkpoint never leaves backing above what the next priced checkpoint
        // gives (NatSpec of _secured: "its collateral, bounded by the IMD that the multiple of its
        // principal buys"). Actual: 1.0 before the touch, about 0.88 after it.
        assertLe(unpriced, priced + 1e12, "an unreadable price must not overstate backing");
    }

    function test_theOverstatementPaysARedeemerAtParFromTheReserve() public {
        vm.startPrank(A);
        vault.lock(1_000 ether);
        vault.draw(500 ether);
        stable.transfer(REDEEMER, 1 ether);
        vm.stopPrank();
        vm.startPrank(B);
        vault.lock(1_000 ether);
        vault.draw(500 ether);
        stable.transfer(REDEEMER, 40 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        vm.mockCallRevert(CHAINLINK_ETH_USD, abi.encodeWithSignature("latestRoundData()"), "dead");
        vm.prank(A);
        vault.wipe(499 ether);
        vm.clearMockedCalls();
        primary.setValue(uint256(0.4 ether) * 1e18 / 2000 ether);

        // Honest backing with A's term at its priced value: (reserve 100 x 0.4 + (1000 + 6) x 0.4) / 501
        // = about 0.883. The fee for 40 of 501 is 4.49%, so the honest payout for 40 imdUSD is
        // 40 x 0.883 x 0.9551 / 0.4 = about 84.3 IMD; at par it is 95.5 IMD, all from the reserve.
        vm.prank(REDEEMER);
        uint256 out = vault.cash(40 ether, 0, B);
        assertLe(out, 89 ether, "paid at the honest backing (about 84.3 IMD), not at par (95.5 IMD)");
    }
}

