            address(imd), address(0), address(0), address(primary), address(health), address(new KeptMirror(primary))
        );
        stable = vault.stablecoin();
        treasury = vault.treasury();
        vm.startPrank(APPROVED_OPERATOR);
        imd.mint(REPAYER, 10_000 ether);
        imd.mint(UNDERWATER, 10_000 ether);
        imd.mint(address(treasury), 500 ether); // the reserve a redemption is paid from first
        vm.stopPrank();
        vm.prank(REPAYER);
        imd.approve(address(vault), type(uint256).max);
        vm.prank(UNDERWATER);
        imd.approve(address(vault), type(uint256).max);
    }

    function _priceUsd(uint256 usd) private {
        primary.set(usd * 1e18 / 2000 ether);
    }

    function test_aTermKeptThroughADeadLegMustNotPayRedeemersAboveTheRepricedBacking() public {
        vm.startPrank(REPAYER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.stopPrank();
        vm.startPrank(UNDERWATER);
        vault.lock(1_700 ether);
        vault.draw(1_000 ether);
        stable.transfer(REDEEMER, 1_000 ether);
        vm.stopPrank();
        vm.warp(block.timestamp + 3 days);
        _priceUsd(0.3 ether); // the crash: 60% and 51%
        vm.prank(REPAYER);
        vault.lock(1);
        vm.prank(UNDERWATER);
        vault.lock(1);
        vm.warp(block.timestamp + 3 days); // warm
        vm.prank(REPAYER);
        vault.lock(1);
        assertLt(vault.backingPerUnit(), 1e18, "the regime: backing below par");

        // The ETH/USD leg dies; the ungated wipe retires 999 of the repayer's 1,000 principal.
        vm.mockCallRevert(CHAINLINK_ETH_USD, abi.encodeWithSignature("latestRoundData()"), "dead");
        vm.prank(REPAYER);
        vault.wipe(999 ether);
        vm.clearMockedCalls();

        uint256 snapshot = vm.snapshotState();
        // What the backing is once the repayer's term is re-priced for its remaining principal.
        vm.prank(REPAYER);
        vault.lock(1);
        uint256 repriced = vault.backingPerUnit();
        vm.prank(REDEEMER);
        uint256 honest = vault.cash(100 ether, 0, address(0));
        vm.revertToState(snapshot);

        uint256 kept = vault.backingPerUnit();
        vm.prank(REDEEMER);
        uint256 paid = vault.cash(100 ether, 0, address(0));
        emit log_named_uint("backing with the term re-priced", repriced);
        emit log_named_uint("backing with the kept term", kept);
        emit log_named_uint("reserve IMD paid for 100 imdUSD, re-priced", honest);
        emit log_named_uint("reserve IMD paid for 100 imdUSD, kept term", paid);
        assertLe(paid, honest + 1, "a term kept through a dead leg must not pay above the re-priced backing");
    }
}
